//! HTTP-level integration tests for `evalfixture::serve` (`ssv2c-evalfixture serve`).
//!
//! A tiny fixture is generated by the real `gen` (seeded, one week, eight frames, no
//! embeddings), served by the product's own API server on an OS-chosen loopback port with
//! `--no-answer`, and driven with `reqwest` over real loopback sockets: no synthetic HTTP
//! anywhere, no model download, no fastembed, nothing touched outside the TempDir. The
//! generator is synchronous (it builds its own runtime internally), so the outer test is a
//! plain `#[test]` and only the HTTP phase runs on a Tokio runtime built afterwards.

use std::time::Duration;

use evalfixture::{gen, serve, API_TOKEN_SETTING, DEFAULT_SEED};
use store::SqliteStore;
use traits::SearchQuery;

/// The tiny fixture shape: one week, eight frames - enough for the search and ask
/// assertions.
const TINY_WEEKS: u32 = 1;
const TINY_FRAMES_PER_WEEK: usize = 8;

/// Status codes asserted raw.
const OK: u16 = 200;
const UNAUTHORIZED: u16 = 401;
const SERVICE_UNAVAILABLE: u16 = 503;

#[test]
fn serve_api_health_auth_search_ask_and_port_release() {
    let temp = tempfile::tempdir().expect("create the fixture tempdir");
    let manifest = gen::generate(&gen::GenOptions {
        out_dir: temp.path().to_path_buf(),
        seed: DEFAULT_SEED,
        weeks: TINY_WEEKS,
        frames_per_week: TINY_FRAMES_PER_WEEK,
        embeddings: false,
    })
    .expect("generate the tiny fixture");

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("build the test runtime");

    runtime.block_on(async {
        // The fixture through the real store: the token `gen` wrote, and a query string
        // the tiny fixture definitely contains.
        let store = SqliteStore::open_path(&manifest.db).expect("open the fixture store");
        let token = store
            .get_setting(API_TOKEN_SETTING)
            .await
            .expect("read api.token")
            .expect("gen wrote api.token into the fixture settings");
        let needle = search_needle(&store, manifest.frames)
            .await
            .expect("a query string the tiny fixture definitely contains");

        let opts = serve::ServeOptions {
            db: manifest.db.clone(),
            data: temp.path().to_path_buf(),
            port: 0,
            embed: false,
            no_answer: true,
        };
        let served = serve::start(&opts).await.expect("start the fixture API");
        let base = format!("http://{}", served.local_addr());
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(20))
            .build()
            .expect("build the HTTP client");

        // GET /v1/health with the fixture token: 200, with honest fixture state.
        let health = client
            .get(format!("{base}/v1/health"))
            .bearer_auth(&token)
            .send()
            .await
            .expect("GET /v1/health with the token");
        assert_eq!(health.status().as_u16(), OK);
        let health: serde_json::Value = health.json().await.expect("health JSON body");
        assert!(
            health["version"].as_str().is_some_and(|v| !v.is_empty()),
            "health body: {health}"
        );
        assert_eq!(health["capturing"], false, "health body: {health}");

        // The same request with no token: 401 with the documented error shape.
        let missing = client
            .get(format!("{base}/v1/health"))
            .send()
            .await
            .expect("GET /v1/health without a token");
        assert_eq!(missing.status().as_u16(), UNAUTHORIZED);
        let missing: serde_json::Value = missing.json().await.expect("401 JSON body");
        assert_eq!(missing["error"], "unauthorized", "401 body: {missing}");
        assert_eq!(
            missing["message"], "missing or invalid bearer token",
            "401 body: {missing}"
        );

        // The same request with a wrong token: the same 401.
        let wrong = client
            .get(format!("{base}/v1/health"))
            .bearer_auth("0".repeat(64))
            .send()
            .await
            .expect("GET /v1/health with a wrong token");
        assert_eq!(wrong.status().as_u16(), UNAUTHORIZED);
        let wrong: serde_json::Value = wrong.json().await.expect("401 JSON body");
        assert_eq!(wrong["error"], "unauthorized", "401 body: {wrong}");
        assert_eq!(
            wrong["message"], "missing or invalid bearer token",
            "401 body: {wrong}"
        );

        // GET /v1/search?q=<the needle>&limit=5 with the token: 200, a non-empty JSON
        // array, and every returned frame_id exists in the fixture database.
        let search = client
            .get(format!("{base}/v1/search"))
            .query(&[("q", needle.as_str()), ("limit", "5")])
            .bearer_auth(&token)
            .send()
            .await
            .expect("GET /v1/search");
        assert_eq!(search.status().as_u16(), OK);
        let hits: serde_json::Value = search.json().await.expect("search JSON body");
        let hits = hits.as_array().expect("/v1/search returns a JSON array");
        assert!(!hits.is_empty(), "the needle must find a fixture frame");
        for hit in hits {
            let frame_id = hit["frame_id"]
                .as_i64()
                .unwrap_or_else(|| panic!("frame_id missing in hit {hit}"));
            let frame = store.get_frame(frame_id).await.expect("get_frame");
            assert!(
                frame.is_some(),
                "returned frame_id {frame_id} must exist in the fixture database"
            );
        }

        // POST /v1/ask under --no-answer: 503 with the documented no-model error, as read
        // from the route (crates/api/src/routes.rs: ApiError::Unavailable("answer model
        // not loaded")).
        let ask = client
            .post(format!("{base}/v1/ask"))
            .bearer_auth(&token)
            .json(&serde_json::json!({ "query": needle }))
            .send()
            .await
            .expect("POST /v1/ask");
        assert_eq!(ask.status().as_u16(), SERVICE_UNAVAILABLE);
        let ask: serde_json::Value = ask.json().await.expect("503 JSON body");
        assert_eq!(ask["error"], "unavailable", "503 body: {ask}");
        assert_eq!(ask["message"], "answer model not loaded", "503 body: {ask}");

        // stop() releases the port: a second start on the same port afterwards succeeds.
        let port = served.local_addr().port();
        served.stop().await;
        let restart_opts = serve::ServeOptions { port, ..opts };
        let restart = serve::start(&restart_opts)
            .await
            .expect("restart the fixture API on the same port");
        assert_eq!(restart.local_addr().port(), port);
        restart.stop().await;
    });

    temp.close().expect("clean up the fixture tempdir");
}

/// Picks a query string the tiny fixture definitely contains: candidate tokens from the
/// frames' stored content text (the exact text `gen` fed through `insert_ocr_filtered`,
/// so its terms sit in the content FTS index), longest first, returning the first one the
/// product's own search over the fixture actually finds. Verifying through the store -
/// not through the server under test - keeps "definitely contains" true by construction
/// while the HTTP assertions still exercise the whole serve surface: auth, status codes,
/// the JSON array shape and the frame-id consistency.
async fn search_needle(store: &SqliteStore, frames: u64) -> Option<String> {
    let mut candidates: Vec<String> = Vec::new();
    for id in 1..=frames as i64 {
        let Ok(Some(detail)) = store.get_frame(id).await else {
            continue;
        };
        let Some(text) = detail.content_text.as_deref() else {
            continue;
        };
        candidates.extend(
            text.split(|c: char| !c.is_ascii_alphanumeric())
                .filter(|token| token.len() >= 4)
                .map(str::to_string),
        );
    }
    candidates.sort();
    candidates.dedup();
    candidates.sort_by_key(|token| std::cmp::Reverse(token.len()));
    for token in &candidates {
        let query = SearchQuery {
            text: token.clone(),
            limit: 5,
            time_range: None,
            include_chrome: false,
        };
        if let Ok(hits) = store.hybrid_search(&query).await {
            if !hits.is_empty() {
                return Some(token.clone());
            }
        }
    }
    None
}
